  const badge = Object.prototype.hasOwnProperty.call(BADGES[domain], status) ? BADGES[domain][status] : undefined;
  return badge ? { ...badge } : { label: status, tone: UNKNOWN_TONE };
}

export function knownStatuses(domain: BadgeDomain): string[] {
  return Object.keys(BADGES[domain]).sort();
}
